package main

import (
	"sync"
	"time"
)

type NodeRole int
const (
	Follower NodeRole = iota
	Candidate
	Leader
)

type RaftNode struct {
	mu        sync.Mutex
	id        int
	currentTerm int
	votedFor    int
	role        NodeRole
	log         []LogEntry
	heartbeat   chan bool
}

// startElection starts a new leader election cycle when the heartbeat timeout expires.
func (rn *RaftNode) startElection() {
	rn.mu.Lock()
	rn.role = Candidate
	rn.currentTerm++
	rn.votedFor = rn.id
	rn.mu.Unlock()

	votesReceived := 1
	for _, peer := range rn.getPeers() {
		go func(p Peer) {
			args := RequestVoteArgs{
				Term:        rn.currentTerm,
				CandidateId: rn.id,
			}
			reply := RequestVoteReply{}
			if rn.sendRequestVote(p, &args, &reply) {
				rn.mu.Lock()
				defer rn.mu.Unlock()
				if reply.VoteGranted && rn.role == Candidate {
					votesReceived++
					if votesReceived > (len(rn.getPeers())+1)/2 {
						rn.role = Leader
						rn.startHeartbeats()
					}
				}
			}
		}(peer)
	}
}

import React, { useEffect, useRef } from 'react';

export const RealTimeChart = ({ dataPoints }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;

    // Resize for high DPI screens
    canvas.width = canvas.clientWidth * dpr;
    canvas.height = canvas.clientHeight * dpr;
    ctx.scale(dpr, dpr);

    // Draw chart grid and path
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = 'rgba(99, 102, 241, 0.8)'; // Electric indigo
    ctx.lineWidth = 2.5;
    ctx.beginPath();

    const step = canvas.clientWidth / (dataPoints.length - 1);
    dataPoints.forEach((point, index) => {
      const x = index * step;
      const y = canvas.clientHeight - (point.value * canvas.clientHeight);
      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();
  }, [dataPoints]);

  return <canvas ref={canvasRef} className="w-full h-64 bg-slate-900 rounded-lg p-4" />;
};
